"""VR rule coverage report (T-01). Regenerated by `python -m rq1.schema.coverage`, never hand-edited."""
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from rq1.fixtures.vr_cases import CASES

from . import registry

ACTIVE = [*range(1, 6), *range(10, 22), 30, 31, 32, 34, 40, 41, *range(50, 56), *range(60, 63), 70, 71]
DEFERRED = {
    40: "Text in section 1.4. It constrains reports and exports, so it is enforced in T-15.",
}
PARTIAL = {
    3: "NaN and infinity are checked. The contract does not enumerate sentinel values, so the sentinel clause has no check (CR-001).",
    52: "Amended by F.1 A3 RC-03. Tested at record level.",
}


@dataclass(frozen=True)
class RuleStatus:
    status: str  # implemented, deferred, blocked_no_text
    note: str


def vr_status() -> dict[str, RuleStatus]:
    cased = {c.rule: c for c in CASES}
    report: dict[str, RuleStatus] = {}
    for number in ACTIVE:
        rule = f"VR-E-{number:03d}"
        if rule in cased:
            report[rule] = RuleStatus("implemented", PARTIAL.get(number, cased[rule].citation))
        elif number in DEFERRED:
            report[rule] = RuleStatus("deferred", DEFERRED[number])
        else:
            report[rule] = RuleStatus("blocked_no_text", "No rule text in the normative documents (CR-001).")
    return report


def render() -> str:
    status = vr_status()
    counts = {s: sum(1 for x in status.values() if x.status == s) for s in ("implemented", "deferred", "blocked_no_text")}
    lines = ["# T-01 VR failing-fixture coverage", "",
             "Generated by `python -m rq1.schema.coverage`. Do not edit by hand.", "",
             f"Active VR rules: {len(status)}. Implemented with a failing fixture: {counts['implemented']}. "
             f"Deferred to a later task: {counts['deferred']}. Blocked, no contract text: {counts['blocked_no_text']}.", "",
             "| Rule | Status | Note |", "|---|---|---|"]
    lines += [f"| {r} | {s.status} | {s.note} |" for r, s in sorted(status.items())]
    tables = registry.TABLES.values()
    inferred = sorted(t.name for t in tables if t.types_inferred)
    provisional = sorted(f"{t.name}.{f.name}" for t in tables for f in t.fields if f.provisional)
    lines += ["", "## Schema items recorded in CR-002", "",
              f"Tables registered: {len(registry.TABLES)}.", "",
              f"Tables whose column types are inferred because the contract lists names only ({len(inferred)}): {', '.join(inferred)}.", "",
              f"Provisional columns ({len(provisional)}): {', '.join(provisional)}.", ""]
    return "\n".join(lines)


if __name__ == "__main__":
    target = Path("reports/T-01_vr_coverage.md")
    target.parent.mkdir(exist_ok=True)
    target.write_text(render(), encoding="utf-8")
    print(target)
